using Microsoft.OpenApi;
using Swashbuckle.AspNetCore.SwaggerGen;

namespace Click2Approve.WebApi.Extensions;

/// <summary>
/// Describes the tenant route parameter resolved by tenant middleware.
/// </summary>
public sealed class TenantRouteParameterOperationFilter : IOperationFilter
{
    /// <summary>
    /// Adds the description to the route parameter generated by Swagger.
    /// </summary>
    public void Apply(OpenApiOperation operation, OperationFilterContext context)
    {
        var parameter = operation.Parameters?
            .OfType<OpenApiParameter>()
            .FirstOrDefault(item => item.Name == "tenantGlobalId" && item.In == ParameterLocation.Path);
        if (parameter is not null)
        {
            parameter.Description = "The tenant ID.";
        }
    }
}
